import{_t as e,it as t,n,rt as r}from"./chunks/framework.B5d4da8a.js";var i=JSON.parse('{"title":"host-cli is a dumb host; ext-* extensions load dynamically","description":"","frontmatter":{"title":"`host-cli` is a dumb host; `ext-*` extensions load dynamically","type":"adr","date":"2026-10-17T00:00:00.000Z","status":"accepted","applies_to":"`host-cli` (renamed from `cli`), `host-lsp` (renamed from `lsp`), `ext-*` (new), `host`, `kernel`"},"headers":[],"relativePath":"handl/project/adrs/0149-dynamic-extension-host.md","filePath":"vendored/handl/project/adrs/0149-dynamic-extension-host.md"}'),a={name:`handl/project/adrs/0149-dynamic-extension-host.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<h1 id="adr-0149-host-cli-is-a-dumb-host-ext-extensions-load-dynamically" tabindex="-1">ADR-0149: <code>host-cli</code> is a dumb host; <code>ext-*</code> extensions load dynamically <a class="header-anchor" href="#adr-0149-host-cli-is-a-dumb-host-ext-extensions-load-dynamically" aria-label="Permalink to “ADR-0149: host-cli is a dumb host; ext-* extensions load dynamically”">​</a></h1><h2 id="context" tabindex="-1">Context <a class="header-anchor" href="#context" aria-label="Permalink to “Context”">​</a></h2><p><code>host-cli</code> hardcodes every tool (<code>run</code>, <code>eval</code>, <code>fmt</code>, <code>lint</code>, <code>typecheck</code>, <code>test</code>, <code>compile</code>, <code>sdkgen</code>, …) as a static dispatch arm, and each tool&#39;s wiring crate (<code>plugin-ext-*</code>) lives in <code>platform</code>. Adding a tool means editing the host&#39;s dispatch and rebuilding the host. That couples the CLI surface to the platform&#39;s release cadence and contradicts the org&#39;s own host/wire model: the host should provide capabilities; plugins should consume them — direction the CLI itself never honored.</p><h2 id="decision" tabindex="-1">Decision <a class="header-anchor" href="#decision" aria-label="Permalink to “Decision”">​</a></h2><ol><li><strong>The host knows nothing about tools.</strong> <code>host-cli</code> exposes exactly one mechanism: discover extensions, read their manifest, register the commands they declare, dispatch argv to them. No <code>match</code> arm per tool; there are no &quot;built-in&quot; tools.</li><li><strong>Extensions are dynamic.</strong> An extension is a shared library (cdylib) — <code>libhnl_ext_&lt;name&gt;.{so,dylib,dll}</code> — discovered at runtime, never a cargo dependency of the host. <code>cargo build</code> of <code>host-cli</code> produces a host that can only report its loaded extension set.</li><li><strong>The ABI is JSON over a C boundary.</strong> Three exported symbols per extension: <ul><li><code>handl_ext_manifest() -&gt; char*</code> — <code>{&quot;name&quot;,&quot;version&quot;,&quot;commands&quot;:[{name,usage}]}</code></li><li><code>handl_ext_dispatch(cmd: *const c_char, input: *const c_char) -&gt; char*</code> — <code>input</code> = <code>{&quot;args&quot;:[..], &quot;cwd&quot;:.., &quot;env&quot;:{..}}</code>; returns <code>{&quot;code&quot;:int, &quot;stdout&quot;:.., &quot;stderr&quot;:..}</code>.</li><li><code>handl_ext_free(char*)</code> — extension-owned strings freed by the extension that allocated them. JSON keeps the boundary free of Rust-type ABI fragility (<code>TaggedValue</code>/<code>serde_json</code> shapes stay inside each side). Marshalling reuses the conventions in <code>plugin-ffi</code>.</li></ul></li><li><strong>One repo per extension</strong> (<code>ext-fmt</code>, <code>ext-lint</code>, <code>ext-typecheck</code>, <code>ext-eval</code>, <code>ext-test</code>, <code>ext-compile</code>, <code>ext-sdkgen</code>, …), same ADR-0128 recipe as <code>lib-*</code>: crate <code>hnl-ext-&lt;name&gt;</code> (cdylib + rlib), git dep <code>branch = &quot;main&quot;</code>, local <code>[patch]</code> dev-link. <code>plugin-ext-diag</code> stays in <code>platform</code> — it is shared diagnostic plumbing, not a tool.</li><li><strong>Discovery</strong>: <code>--ext-dir &lt;dir&gt;</code> flag, else <code>$HANDL_EXT_DIR</code>, else <code>~/.handl/ext/</code>; dev builds additionally scan <code>&lt;exe-dir&gt;/ext/</code> and the workspace <code>target/debug/</code> for <code>libhnl_ext_*</code>. Loading is eager at startup (manifest read only — no tool code runs until its command is dispatched).</li></ol><h2 id="consequences" tabindex="-1">Consequences <a class="header-anchor" href="#consequences" aria-label="Permalink to “Consequences”">​</a></h2><ul><li>Tooling ships on its own release cadence; the host pins nothing.</li><li>The <code>Extension</code>/<code>Plugin</code> substrate stays where it is — extensions are <em>hosts of plugins</em>, and internally keep using the same <code>DefaultHost</code>/<code>CapabilityRequest</code> machinery; only the packaging changes.</li><li><code>ext-*</code> crates still compile to <code>rlib</code> for tests — unit tests link statically; only the shipped artifact is dynamic.</li><li>Repo renames <code>cli</code>→<code>host-cli</code>, <code>lsp</code>→<code>host-lsp</code> make the host/tool split legible in the org.</li><li>Deliberately out of scope: wasm-component extensions and self-hosted <code>.hnl</code> extensions — both need RFC-0001&#39;s story; the JSON ABI chosen here does not preclude either.</li></ul>`,7)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};